[
  {
    "role": "assistant",
    "parts": [
      {
        "type": "text",
        "content": "Ich starte mit der Umwelterkundung, weil ich zuerst die verfügbaren Artefakttypen und deren Umfang kennen muss. Ohne diese Übersicht kann ich weder gezielt Evidenz laden noch vollständige Rechenschaft sicherstellen."
      },
      {
        "type": "tool_call",
        "id": "call_Uhd5xcg3eQVhNcKQbYIL3GdO",
        "name": "list_artifacts",
        "arguments": {}
      }
    ],
    "finish_reason": "tool_call"
  }
]

